const getFileByPath = async (filePath: string, basePath: string = '/uploads') => {
  const fullPath = path.join(basePath, filePath);
  if (fs.existsSync(fullPath)) {
    return fs.readFileSync(fullPath, 'utf-8');
  }
  return null;
};

const runPluginCommand = (pluginName: string, args: string) => {
  return new Promise((resolve, reject) => {
    exec(`npx strapi plugin:${pluginName} ${args}`, (error, stdout, stderr) => {
      if (error) {
        reject(error);
        return;
      }
      resolve(stdout);
    });
  });
};

export const buildXmlElement = (tagName: string, content: string, attributes: Record<string, string> = {}): string => {
  const attrString = Object.entries(attributes)
    .map(([key, value]) => `${key}="${value}"`)
    .join(' ');

  const openTag = attrString ? `<${tagName} ${attrString}>` : `<${tagName}>`;
  return `${openTag}${content}</${tagName}>`;
};

const getResourceFromIdentifier = (resourceType: string, identifier: string) => {
  const resourcePath = `${resourceType}::${identifier}`;
  return strapi.db.query(resourcePath as UID.Schema);
};

export const parseXml = (xmlContent: string): Document => {
  const parser = new DOMParser();
  return parser.parseFromString(xmlContent, 'text/xml');
};
